    /// <summary>linecache: the lines of source files, read once and cached.</summary>
    internal static class linecache
    {
        /// <summary>filename → (size, mtime, lines, fullname), like CPython's cache.</summary>
        public static readonly OrderedDictionary<string, (long, double, List<string>, string)> cache = new OrderedDictionary<string, (long, double, List<string>, string)>();
        static readonly object _lock = new object();

        /// <summary>getline(filename, lineno): the line with its newline, or '' when the file or line does not exist.</summary>
        public static string getline(string filename, long lineno, object? module_globals = null)
        {
            var lines = getlines(filename, module_globals);
            return lineno >= 1 && lineno <= lines.Count ? lines[(int)lineno - 1] : "";
        }

        /// <summary>getlines(filename): the file's lines (each with its newline), or [] when it cannot be read.</summary>
        public static List<string> getlines(string filename, object? module_globals = null)
        {
            lock (_lock)
            {
                if (cache.TryGetValue(filename, out var entry)) return entry.Item3;
            }
            try { return updatecache(filename, module_globals); }
            catch (Exception) { return new List<string>(); }
        }

        /// <summary>updatecache(filename): (re)reads a file into the cache; [] when it cannot be read.</summary>
        public static List<string> updatecache(string filename, object? module_globals = null)
        {
            lock (_lock) cache.Remove(filename);
            if (string.IsNullOrEmpty(filename) || (filename.StartsWith("<") && filename.EndsWith(">"))) return new List<string>();
            string full = filename;
            try
            {
                if (!System.IO.File.Exists(full)) return new List<string>();
                var info = new System.IO.FileInfo(full);
                string text = System.IO.File.ReadAllText(full);
                var lines = SplitLines(text);
                double mtime = (info.LastWriteTimeUtc - DateTime.UnixEpoch).TotalSeconds;
                lock (_lock) cache[filename] = (info.Length, mtime, lines, full);
                return lines;
            }
            catch (Exception) { return new List<string>(); }
        }

        /// <summary>Python's str.splitlines(keepends=True), with a newline added to a last line that lacks one.</summary>
        static List<string> SplitLines(string text)
        {
            var lines = new List<string>();
            int start = 0;
            for (int i = 0; i < text.Length; i++)
            {
                if (text[i] == '\n' || text[i] == '\r')
                {
                    int end = text[i] == '\r' && i + 1 < text.Length && text[i + 1] == '\n' ? i + 2 : i + 1;
                    lines.Add(text.Substring(start, end - start));
                    start = end; i = end - 1;
                }
            }
            if (start < text.Length) lines.Add(text.Substring(start) + "\n");
            return lines;
        }

        /// <summary>clearcache(): forgets every file.</summary>
        public static void clearcache() { lock (_lock) cache.Clear(); }

        /// <summary>checkcache(filename=None): drops the entries of files that changed on disk (or all of them).</summary>
        public static void checkcache(string? filename = null)
        {
            lock (_lock)
            {
                var names = filename == null ? cache.Keys.ToList() : cache.ContainsKey(filename) ? new List<string> { filename } : new List<string>();
                foreach (var name in names)
                {
                    var (size, mtime, _, full) = cache[name];
                    try
                    {
                        var info = new System.IO.FileInfo(full);
                        if (!info.Exists || info.Length != size || (info.LastWriteTimeUtc - DateTime.UnixEpoch).TotalSeconds != mtime) cache.Remove(name);
                    }
                    catch (Exception) { cache.Remove(name); }
                }
            }
        }

        /// <summary>lazycache(filename, module_globals): CPython defers loading from an import loader; Typhon reads files directly (False).</summary>
        public static bool lazycache(string filename, object? module_globals = null) => false;
    }

    /// <summary>traceback: printing and inspecting tracebacks (see the file header for what differs from CPython).</summary>
    internal static class traceback
    {
        /// <summary>One frame of a traceback: file, line, function and source line; unpacks as (filename, lineno, name, line).</summary>
        internal sealed class FrameSummary : IPyRepr, IEnumerable<object?>
        {
            public string filename;
            public long lineno;
            public string name;
            string? _line;
            public object? locals;
            public long? end_lineno, colno, end_colno;
            public FrameSummary(string filename, long lineno, string name, bool lookup_line = true, object? locals = null, string? line = null, long? end_lineno = null, long? colno = null, long? end_colno = null)
            {
                this.filename = filename; this.lineno = lineno; this.name = name; _line = line; this.locals = locals;
                this.end_lineno = end_lineno ?? lineno; this.colno = colno; this.end_colno = end_colno;
                if (lookup_line) _ = this.line;
            }
            /// <summary>The source line, stripped (read from the file the first time).</summary>
            public string? line
            {
                get
                {
                    if (_line == null && lineno > 0) _line = linecache.getline(filename, lineno).Trim();
                    return _line;
                }
            }
            public void Deconstruct(out string filename, out long lineno, out string name, out string? line) { filename = this.filename; lineno = this.lineno; name = this.name; line = this.line; }
            public object? this[long i] => i switch { 0 or -4 => filename, 1 or -3 => lineno, 2 or -2 => name, 3 or -1 => line, _ => throw new ArgumentOutOfRangeException(null, "tuple index out of range") };
            public long __len__() => 4;
            public IEnumerator<object?> GetEnumerator() { yield return filename; yield return lineno; yield return name; yield return line; }
            IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
            public override bool Equals(object? obj) => obj switch
            {
                FrameSummary f => f.filename == filename && f.lineno == lineno && f.name == name && f.locals == locals,
                ITuple t when t.Length == 4 => Builtins.eq(t[0], filename) && Builtins.eq(t[1], lineno) && Builtins.eq(t[2], name) && Builtins.eq(t[3], line),
                _ => false,
            };
            public override int GetHashCode() => HashCode.Combine(filename, lineno, name);
            public string __repr__() => $"<FrameSummary file {filename}, line {lineno} in {name}>";
            public override string ToString() => __repr__();
        }

        /// <summary>A list of FrameSummary objects, oldest frame first.</summary>
        internal sealed class StackSummary : List<FrameSummary>, IPyRepr
        {
            public StackSummary() { }
            public StackSummary(IEnumerable<FrameSummary> frames) : base(frames) { }

            /// <summary>StackSummary.from_list(a_list): from FrameSummary objects or (filename, lineno, name, line) tuples.</summary>
            public static StackSummary from_list(IEnumerable a_list)
            {
                var s = new StackSummary();
                foreach (var x in a_list) s.Add(ToFrame(x));
                return s;
            }

            /// <summary>The frames as CPython prints them: '  File "f.py", line 3, in g\n    source\n' each.</summary>
            public List<string> format()
            {
                var result = new List<string>();
                // CPython folds more than 3 repeats of the same frame into "[Previous line repeated N more times]"
                string? last = null; int repeats = 0;
                foreach (var f in this)
                {
                    string key = f.filename + "\0" + f.lineno + "\0" + f.name;
                    if (key == last) { repeats++; if (repeats >= 3) continue; }
                    else
                    {
                        if (repeats >= 3) result.Add($"  [Previous line repeated {repeats - 2} more time{(repeats - 2 == 1 ? "" : "s")}]\n");
                        last = key; repeats = 0;
                    }
                    result.Add(format_frame_summary(f));
                }
                if (repeats >= 3) result.Add($"  [Previous line repeated {repeats - 2} more time{(repeats - 2 == 1 ? "" : "s")}]\n");
                return result;
            }

            public string format_frame_summary(FrameSummary f) =>
                $"  File \"{f.filename}\", line {f.lineno}, in {f.name}\n" + (string.IsNullOrEmpty(f.line) ? "" : $"    {f.line}\n");

            public string __repr__() => "[" + string.Join(", ", this.Select(f => f.__repr__())) + "]";
            public override string ToString() => __repr__();
        }

        static FrameSummary ToFrame(object? x) => x switch
        {
            FrameSummary f => f,
            ITuple t when t.Length == 4 => new FrameSummary(Builtins.str(t[0]), Convert.ToInt64(t[1]), Builtins.str(t[2]), line: t[3] as string),
            _ => throw new InvalidCastException("expected a FrameSummary or a (filename, lineno, name, line) tuple"),
        };

        /// <summary>The Typhon frames of a .NET stack, oldest first (frames of runtime and .NET code are left out).</summary>
        static StackSummary Frames(IEnumerable<StackFrame>? frames, object? limit)
        {
            var s = new StackSummary();
            if (frames == null) return s;
            foreach (var f in frames.Reverse())
                if (PyFrames.Of(f) is var (file, line, func)) s.Add(new FrameSummary(file, line, func));
            if (limit is long n)
            {
                // limit >= 0: the first n (oldest) of a traceback; negative: the last |n|
                if (n >= 0 && s.Count > n) s.RemoveRange((int)n, s.Count - (int)n);
                else if (n < 0 && s.Count > -n) s.RemoveRange(0, s.Count + (int)n);
            }
            return s;
        }

        /// <summary>The frames an exception passed through (its traceback), or the current stack for a .NET StackTrace.</summary>
        static StackSummary TbFrames(object? tb, object? limit) => tb switch
        {
            null => new StackSummary(),
            Exception e => Frames(new StackTrace(e, true).GetFrames(), limit),
            StackTrace st => Frames(st.GetFrames(), limit),
            StackSummary ss => ss,
            _ => throw new InvalidCastException($"expected a traceback, not {Builtins.PyTypeName(tb.GetType())}"),
        };

        static Exception? Current => PyExcInfo.Current;

        static void Write(object? file, string text)
        {
            if (file == null) { Console.Out.Flush(); Console.Error.Write(text); Console.Error.Flush(); }
            else ((dynamic)file).write(text);
        }

        // ── extract / format / print a traceback ──

        /// <summary>extract_tb(tb, limit=None): the frames of a traceback (an exception stands for its own traceback).</summary>
        public static StackSummary extract_tb(object? tb, object? limit = null) => TbFrames(tb, limit);
        public static List<string> format_tb(object? tb, object? limit = null) => TbFrames(tb, limit).format();
        public static void print_tb(object? tb, object? limit = null, object? file = null) => Write(file, string.Concat(format_tb(tb, limit)));

        /// <summary>extract_stack(f=None, limit=None): the current stack, oldest frame first, without this call.</summary>
        public static StackSummary extract_stack(object? f = null, object? limit = null)
        {
            var s = Frames(new StackTrace(1, true).GetFrames(), null);
            if (limit is long n && s.Count > Math.Abs(n)) s.RemoveRange(0, s.Count - (int)Math.Abs(n));
            return s;
        }
        public static List<string> format_stack(object? f = null, object? limit = null)
        {
            var s = Frames(new StackTrace(1, true).GetFrames(), null);
            if (limit is long n && s.Count > Math.Abs(n)) s.RemoveRange(0, s.Count - (int)Math.Abs(n));
            return s.format();
        }
        public static void print_stack(object? f = null, object? limit = null, object? file = null)
        {
            var s = Frames(new StackTrace(1, true).GetFrames(), null);
            if (limit is long n && s.Count > Math.Abs(n)) s.RemoveRange(0, s.Count - (int)Math.Abs(n));
            Write(file, string.Concat(s.format()));
        }

        /// <summary>format_list(extracted_list): FrameSummary objects or (filename, lineno, name, line) tuples as text.</summary>
        public static List<string> format_list(IEnumerable extracted_list) => StackSummary.from_list(extracted_list).format();

        public static IEnumerable<(object?, long)> walk_tb(object? tb) => TbFrames(tb, null).Select(f => ((object?)f, f.lineno));
        public static IEnumerable<(object?, long)> walk_stack(object? f = null) => Frames(new StackTrace(1, true).GetFrames(), null).AsEnumerable().Reverse().Select(x => ((object?)x, x.lineno));
        public static void clear_frames(object? tb) { }

        // ── exceptions ──

        /// <summary>The last line of a traceback: "ValueError: message" (just the name when the message is empty).</summary>
        public static List<string> format_exception_only(object? exc, object? value = null, bool show_group = false)
        {
            var e = value as Exception ?? exc as Exception;
            if (e == null)
            {
                if (exc is Type t) return new List<string> { Builtins.PyTypeName(t) + "\n" };
                return new List<string> { "NoneType: None\n" };
            }
            return new TracebackException(e).format_exception_only(show_group);
        }

        /// <summary>
        /// format_exception(exc, /, value=..., tb=..., limit=None, chain=True): the lines print_exception prints: the
        /// traceback (when the exception was raised) and the exception line.
        /// </summary>
        public static List<string> format_exception(object? exc, object? value = null, object? tb = null, object? limit = null, bool chain = true)
        {
            var e = value as Exception ?? exc as Exception;
            if (e == null) return format_exception_only(exc, value);
            return new TracebackException(e, limit: limit).format(chain).ToList();
        }

        public static void print_exception(object? exc, object? value = null, object? tb = null, object? limit = null, object? file = null, bool chain = true) =>
            Write(file, string.Concat(format_exception(exc, value, tb, limit, chain)));

        /// <summary>format_exc(): the traceback of the exception being handled (the last one raised on this thread).</summary>
        public static string format_exc(object? limit = null, bool chain = true) =>
            Current is Exception e ? string.Concat(format_exception(e, limit: limit, chain: chain)) : "NoneType: None\n";

        public static void print_exc(object? limit = null, object? file = null, bool chain = true) => Write(file, format_exc(limit, chain));

        /// <summary>print_last(): CPython prints sys.last_exc (the last uncaught exception); Typhon has none in a running program.</summary>
        public static void print_last(object? limit = null, object? file = null, bool chain = true) =>
            throw new ArgumentException("no last exception");

        /// <summary>
        /// An exception ready for formatting: its type, its frames (stack), str(exc), and for a SyntaxError the location.
        /// TracebackException.from_exception(exc) / TracebackException(type(e), e, tb).
        /// </summary>
        internal sealed class TracebackException : IPyRepr
        {
            readonly Exception _exc;
            public readonly Type exc_type;
            public readonly string exc_type_str;
            public readonly StackSummary stack;
            public readonly string _str;
            public readonly List<string>? __notes__ = null;
            public readonly object? __cause__ = null, __context__ = null;
            public readonly bool __suppress_context__ = false;
            public readonly List<TracebackException>? exceptions;
            // SyntaxError's location
            public readonly object? filename, lineno, end_lineno, text, offset, end_offset, msg;

            public TracebackException(Type exc_type, Exception exc_value, object? exc_traceback, object? limit = null, bool lookup_lines = true, bool capture_locals = false, bool compact = false, long max_group_width = 15, long max_group_depth = 10)
                : this(exc_value, limit) { }

            public TracebackException(Exception exc, object? limit = null)
            {
                _exc = exc;
                exc_type = exc.GetType();
                exc_type_str = PyExc.QualifiedName(exc);
                stack = Frames(new StackTrace(exc, true).GetFrames(), limit);
                _str = Builtins.str(exc);
                if (exc is SyntaxError se)
                {
                    filename = se.filename; lineno = se.lineno; end_lineno = se.end_lineno; text = se.text;
                    offset = se.offset; end_offset = se.end_offset; msg = se.msg;
                }
                if (exc is BaseExceptionGroup g) exceptions = g.exceptions.Select(x => new TracebackException(x, limit)).ToList();
            }

            public static TracebackException from_exception(Exception exc, object? limit = null, bool lookup_lines = true, bool capture_locals = false, bool compact = false) =>
                new TracebackException(exc, limit);

            public List<string> format_exception_only(bool show_group = false)
            {
                var result = new List<string>();
                if (_exc is SyntaxError se && se.lineno != null)
                {
                    string file = se.filename is string f ? f : "<string>";
                    result.Add($"  File \"{file}\", line {Builtins.str(se.lineno)}\n");
                    if (se.text is string t)
                    {
                        string stripped = t.TrimEnd('\n', '\r');
                        int lead = stripped.Length - stripped.TrimStart().Length;
                        stripped = stripped.Trim();
                        result.Add($"    {stripped}\n");
                        if (se.offset is long off && off >= 1)
                        {
                            long col = Math.Max(0, off - 1 - lead);
                            long width = se.end_offset is long eo && se.end_lineno is long el && Equals(el, se.lineno) && eo > off ? eo - off : 1;
                            result.Add("    " + new string(' ', (int)Math.Min(col, stripped.Length)) + new string('^', (int)Math.Max(1, width)) + "\n");
                        }
                    }
                    string m = se.msg == null ? "" : Builtins.str(se.msg);
                    result.Add(exc_type_str + (m.Length > 0 ? ": " + m : "") + "\n");
                    return result;
                }
                result.Add(exc_type_str + (_str.Length > 0 ? ": " + _str : "") + "\n");
                if (show_group && exceptions != null)
                    foreach (var sub in exceptions) foreach (var line in sub.format_exception_only(true)) result.Add("   " + line);
                return result;
            }

            /// <summary>The traceback's lines: the header and frames when it has any, then the exception line.</summary>
            public IEnumerable<string> format(bool chain = true, bool _ctx = false)
            {
                if (stack.Count > 0)
                {
                    yield return "Traceback (most recent call last):\n";
                    foreach (var line in stack.format()) yield return line;
                }
                foreach (var line in format_exception_only()) yield return line;
            }

            public void print(object? file = null, bool chain = true) => Write(file, string.Concat(format(chain)));
            public string __str__() => _str;
            public string __repr__() => $"<traceback.TracebackException object at 0x{RuntimeHelpers.GetHashCode(this):x12}>";
            public override string ToString() => _str;
            public override bool Equals(object? obj) => obj is TracebackException o && o.exc_type == exc_type && o._str == _str && o.stack.SequenceEqual(stack);
            public override int GetHashCode() => HashCode.Combine(exc_type, _str);
        }
    }
}
